+    e.preventDefault();
+    setSubmitted({
+      at: new Date().toLocaleTimeString(),
+      counts: QUESTIONS.map((q) => ({
+        id: q.id,
+        prompt: q.prompt,
+        count: answers[q.id].length,
+      })),
+    });
+    requestAnimationFrame(() => {
+      if (statusRef.current) statusRef.current.focus();
+    });
+  };
+
+  return (
+    <>
+      <header className="quiz-header">
+        <h1>Computer Languages Quiz</h1>
+        <p>Three multi-select questions. Select every choice you think applies.</p>
+      </header>
+
+      <form noValidate onSubmit={handleSubmit} aria-labelledby="quiz-heading">
+        {QUESTIONS.map((q) => (
+          <CheckboxQuestion
+            key={q.id}
+            question={q}
+            selected={answers[q.id]}
+            onToggle={toggle}
+          />
+        ))}
+
+        <div className="actions">
+          <button type="submit">Submit answers</button>
+          <span aria-hidden="true" style={{ color: "var(--text-muted)", fontSize: "0.9rem" }}>
+            {totalSelected} selected
+          </span>
+        </div>
+
+        <div aria-live="polite" aria-atomic="true">
+          {submitted && (
+            <p
+              className="status success"
+              ref={statusRef}
+              tabIndex={-1}
+            >
+              Thanks — answers submitted at {submitted.at}.{" "}
+              You picked{" "}
+              {submitted.counts
+                .map((c) => `${c.count} for "${c.prompt}"`)
+                .join("; ")}
+              .
+            </p>
+          )}
+        </div>
+      </form>
+    </>
+  );
+}
+
